<?php
namespace App\Http\Controllers\Api\V1\Desktop;
use App\Http\Controllers\Controller; use App\Http\Requests\Desktop\StoreMediaRequest; use App\Http\Requests\Desktop\StorePhotoSessionRequest; use App\Http\Resources\Desktop\PhotoSessionResource; use App\Models\Device; use App\Models\PhotoSession; use App\Support\ApiResponse; use Illuminate\Support\Facades\Storage; use Illuminate\Support\Str;
class PhotoSessionController extends Controller {
 public function store(StorePhotoSessionRequest $request) { $user=$request->user(); $device=Device::where('device_uuid',$request->header('X-Device-UUID'))->where('status','active')->first(); if(!$device || $device->partner_id !== $user->partner_id || !$device->booth_id) return ApiResponse::error('Active device and booth are required.',null,422); $session=PhotoSession::create(['partner_id'=>$device->partner_id,'booth_id'=>$device->booth_id,'device_id'=>$device->id,'operator_id'=>$user->id,'event_id'=>$request->event_id,'customer_id'=>$request->customer_id,'payment_id'=>$request->payment_id,'download_token'=>Str::random(64),'status'=>'started']); return ApiResponse::success(new PhotoSessionResource($session),'Photo session created.',201); }
 public function media(StoreMediaRequest $request, PhotoSession $photoSession) { $this->authorizeSession($request,$photoSession); $data=$request->data_url; if(!preg_match('/^data:(image\/\w+|video\/\w+|application\/zip);base64,(.+)$/',$data,$m)) return ApiResponse::error('Invalid data_url.',null,422); $binary=base64_decode($m[2],true); if($binary===false) return ApiResponse::error('Invalid base64 payload.',null,422); $key='sessions/'.$photoSession->id.'/'.Str::uuid().'-'.$request->filename; Storage::disk('local')->put($key,$binary); $media=$photoSession->media()->create(['type'=>$request->type,'bucket'=>'local','object_key'=>$key,'filename'=>$request->filename,'mime_type'=>$request->mime_type,'size_bytes'=>strlen($binary),'checksum'=>hash('sha256',$binary),'width'=>$request->width,'height'=>$request->height,'visibility'=>'private']); return ApiResponse::success($media,'Media uploaded.',201); }
 public function complete(StorePhotoSessionRequest $request, PhotoSession $photoSession) { $this->authorizeSession($request,$photoSession); $photoSession->update(['status'=>'completed','completed_at'=>now()]); return ApiResponse::success(new PhotoSessionResource($photoSession->load('media')),'Photo session completed.'); }
 private function authorizeSession($request,PhotoSession $session): void { abort_unless($session->partner_id === $request->user()->partner_id && $session->operator_id === $request->user()->id,403); }
}